/* ---------------- helpers ---------------- */
const rand = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
function shuffle(a) {
  const r = a.slice();
  for (let i = r.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [r[i], r[j]] = [r[j], r[i]]; }
  return r;
}
function gcd(a, b) { a = Math.abs(a); b = Math.abs(b); while (b) { [a, b] = [b, a % b]; } return a || 1; }
function buildMC(correct, distractors, fmt = (x) => String(x)) {
  const seen = new Set([correct]); const pool = [];
  for (const d of distractors) if (Number.isFinite(d) && !seen.has(d) && (d >= 0 || correct < 0)) { seen.add(d); pool.push(d); }
  let guard = 0;
  while (pool.length < 4 && guard < 300) {
    guard++; const delta = rand(1, 9) * (Math.random() < 0.5 ? -1 : 1); const cand = correct + delta;
    if (Number.isFinite(cand) && !seen.has(cand) && (cand >= 0 || correct < 0)) { seen.add(cand); pool.push(cand); }
  }
  const opts = shuffle([correct, ...pool.slice(0, 4)]);
  return { options: opts.map(fmt), correctIndex: opts.indexOf(correct) };
}
function buildMCStr(correct, distractors) {
  const seen = new Set([correct]); const pool = [];
  for (const d of distractors) if (d != null && !seen.has(d)) { seen.add(d); pool.push(d); }
  while (pool.length < 4) pool.push(correct + "·" + pool.length);
  const opts = shuffle([correct, ...pool.slice(0, 4)]);
  return { options: opts, correctIndex: opts.indexOf(correct) };
}
const gbp = (x) => "£" + x;
const deg = (x) => x + "°";
function simplifyFrac(n, d) { const g = gcd(n, d); return [n / g, d / g]; }
function sup(n) { const m = { "-": "⁻", 0: "⁰", 1: "¹", 2: "²", 3: "³", 4: "⁴", 5: "⁵", 6: "⁶", 7: "⁷", 8: "⁸", 9: "⁹" }; return String(n).split("").map((c) => m[c] || c).join(""); }

/* ---------------- SVG helpers ---------------- */
function svgBox(inner, w = 280, h = 220) {
  return `<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg" style="max-width:330px;width:100%;height:auto;display:block;margin:0 auto">${inner}</svg>`;
}
const txt = (x, y, s, opt = {}) =>
  `<text x="${x}" y="${y}" font-family="Fredoka, sans-serif" font-size="${opt.size || 15}" font-weight="600" fill="${opt.fill || T.ink}" text-anchor="${opt.anchor || "middle"}">${s}</text>`;

