          both = rowCands.filter((v) => colCands.includes(v));

          boxKnown = [];
          for (let r = boxR0; r < boxR0 + 2; r++) for (let c = boxC0; c < boxC0 + 2; c++) if (!(r === askR && c === askC)) boxKnown.push(g[r][c]);
          boxCandsRemaining = both.filter((v) => !boxKnown.includes(v));
