          if (r === aR && c === aC) label = "a";
          if (r === askR && c === askC) label = "?";
          s += ST(ox + c * cell + cell / 2, oy + r * cell + cell / 2 + 6, label, "middle", 18, ["a", "b", "?"].includes(label) ? "#7c5cff" : "#2a1a5e", 700);
