          if (r === hideR && c === hideC2) label = "q";
          s += ST(ox + c * cell + cell / 2, oy + r * cell + cell / 2 + 6, label, "middle", 18, (label === "p" || label === "q") ? "#7c5cff" : "#2a1a5e", 700);
